-- V0016 data dictionary: a COMMENT on every app and dw table, view and column (docs/31 s3 item 8). The table comment
-- ends with a metadata line 'owner: ... | capture: ... | retention: ... | pii: ...'; a column holding personal data
-- starts with [pii:personal], [pii:sensitive] or [pii:secret], and the table's pii is the highest of its columns.
-- docs/data-dictionary.md is rendered from these comments (tools/data-dictionary), and DataDictionaryTest fails on any
-- table, view or column without one, so every later migration adds COMMENT ON for what it creates.

COMMENT ON TABLE app.activity_log IS 'One row is a batch of sampled screen and action events from a phone, kept for support and usage analysis.
owner: backend:platform | capture: OFFLINE | retention: telemetry | pii: none';
COMMENT ON COLUMN app.activity_log.id IS 'Server surrogate key.';
COMMENT ON COLUMN app.activity_log.client_uuid IS 'Client-generated UUID v4 of the record; the server upserts by it (idempotency key).';
COMMENT ON COLUMN app.activity_log.family_uuid IS 'client_uuid of the family header the record belongs to (equal to client_uuid on a header).';
COMMENT ON COLUMN app.activity_log.business_date IS 'Asia/Dhaka date of the trusted capture time.';
COMMENT ON COLUMN app.activity_log.business_date_device IS 'Date on the phone''s own clock, kept when the server re-dated the row to a trusted business date.';
COMMENT ON COLUMN app.activity_log.user_id IS 'Database id of the user who captured the record, taken from the token and never from the body.';
COMMENT ON COLUMN app.activity_log.device_id IS 'Database id of the phone that captured the record, from the token.';
COMMENT ON COLUMN app.activity_log.acting_for_user_id IS 'Assignee of the route when the capturing user worked it as a cover substitute.';
COMMENT ON COLUMN app.activity_log.captured_at IS 'UTC instant of capture on the phone, from trusted time when an anchor exists.';
COMMENT ON COLUMN app.activity_log.captured_elapsed_ms IS 'SystemClock.elapsedRealtime() at capture, in milliseconds since boot.';
COMMENT ON COLUMN app.activity_log.boot_count IS 'Android boot counter at capture; with captured_elapsed_ms it anchors trusted time.';
COMMENT ON COLUMN app.activity_log.clock_offset_ms IS 'Server time minus phone wall clock known at capture, in ms; null if the phone never synced.';
COMMENT ON COLUMN app.activity_log.captured_offline IS 'True when the phone had no connection at capture.';
COMMENT ON COLUMN app.activity_log.schema_version IS 'Version of the record payload schema.';
COMMENT ON COLUMN app.activity_log.config_version IS 'Global config version in force for the row (at capture for device records).';
COMMENT ON COLUMN app.activity_log.bundle_version IS 'Version of the day bundle the phone held at capture (<date>:<seq>).';
COMMENT ON COLUMN app.activity_log.bundle_stale IS 'True when the record was captured on a cached bundle older than the business date.';
COMMENT ON COLUMN app.activity_log.first_batch_uuid IS 'batch_uuid of the sync batch that first delivered the record.';
COMMENT ON COLUMN app.activity_log.received_at IS 'UTC instant the server received the row.';
COMMENT ON COLUMN app.activity_log.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.activity_log.voided_at IS 'UTC time an admin data void tombstoned the row; the row is never deleted.';
COMMENT ON COLUMN app.activity_log.external_ref IS 'Stable external reference for cross-walks with other systems (Apsis, ERP); unique when set.';
COMMENT ON COLUMN app.activity_log.events IS 'Array of sampled screen and action events (name, time, detail) from the phone.';

