COMMENT ON COLUMN app.app_error.clock_offset_ms IS 'Server time minus phone wall clock known at capture, in ms; null if the phone never synced.';
COMMENT ON COLUMN app.app_error.captured_offline IS 'True when the phone had no connection at capture.';
COMMENT ON COLUMN app.app_error.schema_version IS 'Version of the record payload schema.';
COMMENT ON COLUMN app.app_error.config_version IS 'Global config version in force for the row (at capture for device records).';
COMMENT ON COLUMN app.app_error.bundle_version IS 'Version of the day bundle the phone held at capture (<date>:<seq>).';
COMMENT ON COLUMN app.app_error.bundle_stale IS 'True when the record was captured on a cached bundle older than the business date.';
COMMENT ON COLUMN app.app_error.first_batch_uuid IS 'batch_uuid of the sync batch that first delivered the record.';
COMMENT ON COLUMN app.app_error.received_at IS 'UTC instant the server received the row.';
COMMENT ON COLUMN app.app_error.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.app_error.voided_at IS 'UTC time an admin data void tombstoned the row; the row is never deleted.';
COMMENT ON COLUMN app.app_error.external_ref IS 'Stable external reference for cross-walks with other systems (Apsis, ERP); unique when set.';
COMMENT ON COLUMN app.app_error.occurred_at IS 'UTC time the error occurred on the phone.';
COMMENT ON COLUMN app.app_error.kind IS 'Kind of the row; allowed values are listed under constraints.';
COMMENT ON COLUMN app.app_error.exception_class IS 'Class name of the exception or ANR reason.';
COMMENT ON COLUMN app.app_error.message IS 'Scrubbed error message text, if any.';
COMMENT ON COLUMN app.app_error.stack IS 'Scrubbed stack trace text, if any.';
COMMENT ON COLUMN app.app_error.screen IS 'Name of the app screen that was open when the error occurred.';
COMMENT ON COLUMN app.app_error.app_version IS 'App version as versionName+versionCode, e.g. 1.0.3+103.';

COMMENT ON TABLE app.app_package IS 'Catalogue of Android packages the portal offers when editing the app block and allow lists, with a category and a suggested rule.
owner: backend:config | capture: ONLINE | retention: master | pii: none';
COMMENT ON COLUMN app.app_package.package_name IS 'Android package name, for example com.example.app.';
COMMENT ON COLUMN app.app_package.label IS 'Human-readable app name shown in the portal.';
COMMENT ON COLUMN app.app_package.category IS 'Catalogue category such as social, video, game, messaging, maps or system.';
COMMENT ON COLUMN app.app_package.suggested_rule IS 'Suggested handling in the device policy: block or allow.';
COMMENT ON COLUMN app.app_package.first_seen_at IS 'UTC time a status report or install list first named the package.';
COMMENT ON COLUMN app.app_package.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.app_package.updated_at IS 'UTC instant of the last update.';

COMMENT ON TABLE app.app_release IS 'One published or draft build of the field app (version, ABI, download URL, signing certificate, rollout percentage).
owner: backend:config | capture: ONLINE | retention: master | pii: none';
COMMENT ON COLUMN app.app_release.id IS 'Server surrogate key.';
COMMENT ON COLUMN app.app_release.flavour IS 'Field app flavour: sr, amo or tso.';
COMMENT ON COLUMN app.app_release.version_name IS 'Display version of the build, for example 1.4.2.';
COMMENT ON COLUMN app.app_release.version_code IS 'Android integer version code; increases with every build.';
COMMENT ON COLUMN app.app_release.abi IS 'CPU architecture of the APK: universal, arm64-v8a or armeabi-v7a.';
COMMENT ON COLUMN app.app_release.sha256 IS 'SHA-256 of the file content.';
COMMENT ON COLUMN app.app_release.size_bytes IS 'APK size in bytes.';
COMMENT ON COLUMN app.app_release.download_url IS 'URL the phone downloads the APK from.';
COMMENT ON COLUMN app.app_release.signing_cert_sha256 IS 'SHA-256 digest of the APK signing certificate.';
COMMENT ON COLUMN app.app_release.status IS 'Lifecycle status; allowed values are listed under constraints.';
COMMENT ON COLUMN app.app_release.rollout_pct IS 'Percentage of devices the release is offered to, 0 to 100.';
COMMENT ON COLUMN app.app_release.notes_en IS 'Release notes in English.';
COMMENT ON COLUMN app.app_release.notes_bn IS 'Release notes in Bangla.';
COMMENT ON COLUMN app.app_release.created_by IS 'User who created the row (null for migrations and jobs).';
COMMENT ON COLUMN app.app_release.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.app_release.published_at IS 'UTC time the release was published.';
COMMENT ON COLUMN app.app_release.published_by IS 'Id of the user who published the release; differs from its author.';
COMMENT ON COLUMN app.app_release.updated_at IS 'UTC instant of the last update.';
COMMENT ON COLUMN app.app_release.version IS 'Optimistic-concurrency version; increases by one on every update.';

COMMENT ON TABLE app.app_user IS 'One person who can log in, field or web, with role, status, locale and Argon2id password hash; never deleted.
owner: backend:masterdata | capture: ONLINE | retention: master | pii: secret';
COMMENT ON COLUMN app.app_user.id IS 'Server surrogate key.';
COMMENT ON COLUMN app.app_user.username IS '[pii:personal] Login name; memo-producing roles embed it in memo numbers.';
COMMENT ON COLUMN app.app_user.full_name IS '[pii:personal] Full name of the user.';
COMMENT ON COLUMN app.app_user.role IS 'User role (contract Role).';
COMMENT ON COLUMN app.app_user.designation IS 'Job title shown on screens and reports.';
COMMENT ON COLUMN app.app_user.employee_code IS '[pii:personal] Employee code from the HR or Apsis record.';
COMMENT ON COLUMN app.app_user.phone IS '[pii:personal] Mobile phone number of the user.';
COMMENT ON COLUMN app.app_user.email IS '[pii:personal] E-mail address.';
COMMENT ON COLUMN app.app_user.locale IS 'Preferred app language: bn or en.';
COMMENT ON COLUMN app.app_user.home_zone_id IS 'Id of the zone the user belongs to by default.';
COMMENT ON COLUMN app.app_user.status IS 'Lifecycle status; allowed values are listed under constraints.';
COMMENT ON COLUMN app.app_user.password_hash IS '[pii:secret] Argon2id password hash in PHC string form; null means no password is set.';
COMMENT ON COLUMN app.app_user.password_changed_at IS 'UTC time the password was last changed.';
COMMENT ON COLUMN app.app_user.must_change_password IS 'True when the user must set a new password at the next login.';
COMMENT ON COLUMN app.app_user.mfa_enabled IS 'True when TOTP is confirmed for the user.';
COMMENT ON COLUMN app.app_user.pilot IS 'True when the user is in the pilot group for the cutover.';
COMMENT ON COLUMN app.app_user.scope_version IS 'Counter bumped on any change of role, status, scope or assignment; tokens carrying an older value are refused.';
COMMENT ON COLUMN app.app_user.last_login_at IS 'UTC time of the most recent successful login.';
COMMENT ON COLUMN app.app_user.disabled_at IS 'UTC time the account was disabled; null while active.';
COMMENT ON COLUMN app.app_user.external_ref IS 'Stable external reference for cross-walks with other systems (Apsis, ERP); unique when set.';
COMMENT ON COLUMN app.app_user.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.app_user.updated_at IS 'UTC instant of the last update.';
COMMENT ON COLUMN app.app_user.version IS 'Optimistic-concurrency version; increases by one on every update.';
COMMENT ON COLUMN app.app_user.created_by IS 'User who created the row (null for migrations and jobs).';
COMMENT ON COLUMN app.app_user.updated_by IS 'User who last updated the row.';

COMMENT ON TABLE app.astha_target IS 'Astha programme target for a route (optionally an outlet and brand) and month, in standard units and memo count.
owner: backend:masterdata | capture: ONLINE | retention: master | pii: none';
COMMENT ON COLUMN app.astha_target.id IS 'Server surrogate key.';
COMMENT ON COLUMN app.astha_target.programme_id IS 'Programme (app.programme); programmes are deferred (docs/27).';
COMMENT ON COLUMN app.astha_target.month IS 'First day of the calendar month.';
COMMENT ON COLUMN app.astha_target.route_id IS 'Route (app.route) being worked.';
COMMENT ON COLUMN app.astha_target.outlet_id IS 'Outlet (app.outlet).';
COMMENT ON COLUMN app.astha_target.brand_id IS 'Product brand (app.product_node of level brand).';
COMMENT ON COLUMN app.astha_target.std_target IS 'Target in standard units for the route, month and brand, with three decimals.';
COMMENT ON COLUMN app.astha_target.memo_target IS 'Target number of memos for the route and month.';
COMMENT ON COLUMN app.astha_target.batch_uuid IS 'UUID of the batch or bulk operation that carried or created the row (idempotency of the batch).';
COMMENT ON COLUMN app.astha_target.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.astha_target.updated_at IS 'UTC instant of the last update.';
COMMENT ON COLUMN app.astha_target.created_by IS 'User who created the row (null for migrations and jobs).';

