COMMENT ON COLUMN app.attendance_event.captured_offline IS 'True when the phone had no connection at capture.';
COMMENT ON COLUMN app.attendance_event.schema_version IS 'Version of the record payload schema.';
COMMENT ON COLUMN app.attendance_event.config_version IS 'Global config version in force for the row (at capture for device records).';
COMMENT ON COLUMN app.attendance_event.bundle_version IS 'Version of the day bundle the phone held at capture (<date>:<seq>).';
COMMENT ON COLUMN app.attendance_event.bundle_stale IS 'True when the record was captured on a cached bundle older than the business date.';
COMMENT ON COLUMN app.attendance_event.sig IS 'ES256 signature by the device key over the record (header records only).';
COMMENT ON COLUMN app.attendance_event.first_batch_uuid IS 'batch_uuid of the sync batch that first delivered the record.';
COMMENT ON COLUMN app.attendance_event.received_at IS 'UTC instant the server received the row.';
COMMENT ON COLUMN app.attendance_event.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.attendance_event.voided_at IS 'UTC time an admin data void tombstoned the row; the row is never deleted.';
COMMENT ON COLUMN app.attendance_event.external_ref IS 'Stable external reference for cross-walks with other systems (Apsis, ERP); unique when set.';
COMMENT ON COLUMN app.attendance_event.kind IS 'Kind of the row; allowed values are listed under constraints.';
COMMENT ON COLUMN app.attendance_event.fix_status IS 'Outcome of the fix request: ok, timeout, permission_denied, location_off or provider_unavailable.';
COMMENT ON COLUMN app.attendance_event.fix_lat IS '[pii:personal] Latitude of the user''s location fix taken with the record (WGS84 degrees).';
COMMENT ON COLUMN app.attendance_event.fix_lng IS '[pii:personal] Longitude of the user''s location fix taken with the record (WGS84 degrees).';
COMMENT ON COLUMN app.attendance_event.fix_accuracy_m IS '[pii:personal] Accuracy in metres of the location fix taken with the record.';
COMMENT ON COLUMN app.attendance_event.fix_is_mock IS 'True when the phone flagged the fix as coming from a mock location provider.';
COMMENT ON COLUMN app.attendance_event.address_display IS 'Reverse-geocoded address shown for display only; never used for a decision.';

COMMENT ON TABLE app.audit_log IS 'Append-only, hash-chained record of web and admin actions with before and after images and the actor.
owner: backend:platform | capture: SERVER | retention: audit | pii: personal';
COMMENT ON COLUMN app.audit_log.id IS 'Server surrogate key.';
COMMENT ON COLUMN app.audit_log.chain_seq IS 'Position in the hash chain, assigned by the insert trigger; strictly increasing.';
COMMENT ON COLUMN app.audit_log.at IS 'UTC time the action was recorded, set by the server.';
COMMENT ON COLUMN app.audit_log.business_date IS 'Asia/Dhaka business date of the row (cutoff 00:00 Dhaka); all day-level rollups key off it.';
COMMENT ON COLUMN app.audit_log.actor_user_id IS 'Id of the user who acted; null for system actions.';
COMMENT ON COLUMN app.audit_log.actor_username IS '[pii:personal] Username of the actor at the time of the action.';
COMMENT ON COLUMN app.audit_log.actor_role IS 'Role of the actor at the time of the action.';
COMMENT ON COLUMN app.audit_log.via IS 'Channel the action came through: device, web, api or job.';
COMMENT ON COLUMN app.audit_log.entity IS 'Type of the thing that was changed, for example outlet or cfg_value.';
COMMENT ON COLUMN app.audit_log.entity_id IS 'Identifier of the changed thing, as text.';
COMMENT ON COLUMN app.audit_log.action IS 'What was done, for example create, update, approve or void.';
COMMENT ON COLUMN app.audit_log.before IS '[pii:personal] JSON image of the entity before the change; may contain personal fields.';
COMMENT ON COLUMN app.audit_log.after IS '[pii:personal] JSON image of the entity after the change; may contain personal fields.';
COMMENT ON COLUMN app.audit_log.reason IS 'Reason given for the change or action (free text).';
COMMENT ON COLUMN app.audit_log.request_id IS 'Request id of the API call that caused the change.';
COMMENT ON COLUMN app.audit_log.ip_class IS 'Coarse class of the caller address; the full address is not stored.';
COMMENT ON COLUMN app.audit_log.prev_hash IS 'row_hash of the previous row in the chain; null for the first row.';
COMMENT ON COLUMN app.audit_log.row_hash IS 'Hash over this row''s content and prev_hash, used to verify the chain.';

COMMENT ON TABLE app.auth_lockout IS 'Failed-login counter and lock state per lock key, shared by every API replica.
owner: backend:auth | capture: SERVER | retention: session | pii: none';
COMMENT ON COLUMN app.auth_lockout.lock_key IS 'Key the counter applies to (for example user or device), per the lockout key mode.';
COMMENT ON COLUMN app.auth_lockout.failures IS 'Failed attempts counted in the current window.';
COMMENT ON COLUMN app.auth_lockout.window_started_at IS 'UTC start of the current failure-counting window.';
COMMENT ON COLUMN app.auth_lockout.locked_until IS 'UTC time the lock ends; null when not locked.';
COMMENT ON COLUMN app.auth_lockout.lock_count IS 'Number of times this key has been locked.';
COMMENT ON COLUMN app.auth_lockout.updated_at IS 'UTC instant of the last update.';

COMMENT ON TABLE app.calendar_holiday IS 'One declared holiday or selling-day override for a geography scope and date.
owner: backend:masterdata | capture: ONLINE | retention: master | pii: none';
COMMENT ON COLUMN app.calendar_holiday.id IS 'Server surrogate key.';
COMMENT ON COLUMN app.calendar_holiday.date IS 'Dhaka calendar date the declaration applies to.';
COMMENT ON COLUMN app.calendar_holiday.scope_type IS 'Level of the scope: global, role, wing, division, territory, geo_class, zone, route, outlet, user or device.';
COMMENT ON COLUMN app.calendar_holiday.scope_id IS 'Id of the scope node; 0 for global; role and geo_class use the app.role_def and app.geo_class_def ordinals.';
COMMENT ON COLUMN app.calendar_holiday.kind IS 'Kind of the row; allowed values are listed under constraints.';
COMMENT ON COLUMN app.calendar_holiday.selling_day IS 'True when selling still happens on this date despite the holiday.';
COMMENT ON COLUMN app.calendar_holiday.name_en IS 'Display name in English.';
COMMENT ON COLUMN app.calendar_holiday.name_bn IS 'Display name in Bangla.';
COMMENT ON COLUMN app.calendar_holiday.reason IS 'Reason given for the change or action (free text).';
COMMENT ON COLUMN app.calendar_holiday.declared_at IS 'UTC time the holiday was declared.';
COMMENT ON COLUMN app.calendar_holiday.created_by IS 'User who created the row (null for migrations and jobs).';
COMMENT ON COLUMN app.calendar_holiday.revoked_at IS 'UTC instant the row was revoked; null while valid.';
COMMENT ON COLUMN app.calendar_holiday.revoked_by IS 'Id of the user who revoked the declaration; null while in force.';

