COMMENT ON COLUMN app.db_role_grant.object IS 'Table or view name, or a value starting with ''*'' for every table of the schema.';
COMMENT ON COLUMN app.db_role_grant.privileges IS 'Comma-separated privileges granted: SELECT, INSERT, UPDATE, DELETE.';
COMMENT ON COLUMN app.db_role_grant.except_tables IS 'Tables a ''*'' row leaves out.';
COMMENT ON COLUMN app.db_role_grant.note IS 'Free-text note.';

COMMENT ON TABLE app.device IS 'One enrolled phone with its status, trust level, key, integrity verdict and last contact.
owner: backend:auth | capture: ONLINE | retention: master | pii: none';
COMMENT ON COLUMN app.device.id IS 'Server surrogate key.';
COMMENT ON COLUMN app.device.device_uuid IS 'UUID the phone generated for itself at enrolment.';
COMMENT ON COLUMN app.device.flavour IS 'Field app flavour: sr, amo or tso.';
COMMENT ON COLUMN app.device.app_package IS 'Android package name of the installed field app.';
COMMENT ON COLUMN app.device.status IS 'Lifecycle status; allowed values are listed under constraints.';
COMMENT ON COLUMN app.device.status_changed_at IS 'UTC instant of the last status change.';
COMMENT ON COLUMN app.device.status_reason IS 'Reason given for the current device status.';
COMMENT ON COLUMN app.device.device_owner IS 'True when the Aron app was device owner of the phone at the time.';
COMMENT ON COLUMN app.device.lockdown_level IS 'Device policy lockdown level: dev or prod.';
COMMENT ON COLUMN app.device.trust_level IS 'Trust level of the device: high, normal, low or blocked.';
COMMENT ON COLUMN app.device.integrity_verdict IS 'Latest integrity result: pass, fail, unevaluated or stale.';
COMMENT ON COLUMN app.device.integrity_checked_at IS 'UTC time the integrity verdict was last evaluated.';
COMMENT ON COLUMN app.device.hardware_backed_key IS 'True when the device key lives in hardware-backed Keystore.';
COMMENT ON COLUMN app.device.public_key_jwk IS 'Public key of the device as a JSON Web Key; used to verify signed records.';
COMMENT ON COLUMN app.device.public_key_thumbprint IS 'RFC 7638 thumbprint of the device key; one device row per Keystore key.';
COMMENT ON COLUMN app.device.attestation_summary IS 'JSON summary of the key attestation: verified boot, security level, package and certificate digest.';
COMMENT ON COLUMN app.device.app_signing_cert_sha256 IS 'SHA-256 of the app signing certificate seen on the device.';
COMMENT ON COLUMN app.device.enrolment_token_id IS 'Id of the enrolment token used to enrol this device.';
COMMENT ON COLUMN app.device.enrolled_at IS 'UTC time the device enrolled.';
COMMENT ON COLUMN app.device.device_info IS 'JSON device information (model, OS version and similar) reported by the phone.';
COMMENT ON COLUMN app.device.app_version IS 'App version as versionName+versionCode, e.g. 1.0.3+103.';
COMMENT ON COLUMN app.device.policy_version_applied IS 'Device policy version the phone last reported applying.';
COMMENT ON COLUMN app.device.config_version_applied IS 'Config version the phone last reported applying.';
COMMENT ON COLUMN app.device.last_contact_at IS 'UTC time of the last request from the device.';
COMMENT ON COLUMN app.device.pending_rows_reported IS 'Rows waiting to upload that the phone last reported.';
COMMENT ON COLUMN app.device.zone_id IS 'Zone (app.zone).';
COMMENT ON COLUMN app.device.replaced_by_device_id IS 'Id of the device that replaced this one.';
COMMENT ON COLUMN app.device.external_ref IS 'Stable external reference for cross-walks with other systems (Apsis, ERP); unique when set.';
COMMENT ON COLUMN app.device.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.device.updated_at IS 'UTC instant of the last update.';
COMMENT ON COLUMN app.device.version IS 'Optimistic-concurrency version; increases by one on every update.';

COMMENT ON TABLE app.device_binding IS 'Link of a user to a phone, with the binding ordinal that fixes the memo-number block.
owner: backend:auth | capture: ONLINE | retention: audit | pii: none';
COMMENT ON COLUMN app.device_binding.id IS 'Server surrogate key.';
COMMENT ON COLUMN app.device_binding.device_id IS 'Phone (app.device) the row came from, taken from the token, never from the body.';
COMMENT ON COLUMN app.device_binding.user_id IS 'User (app.app_user); for device records the capturing user from the token.';
COMMENT ON COLUMN app.device_binding.bind_ordinal IS 'Binding slot 0 to 3 of the user on the device; selects the memo-number block.';
COMMENT ON COLUMN app.device_binding.status IS 'Lifecycle status; allowed values are listed under constraints.';
COMMENT ON COLUMN app.device_binding.bound_at IS 'UTC time the user was bound to the device.';
COMMENT ON COLUMN app.device_binding.bound_via IS 'How the binding was made: otp, support or migration.';
COMMENT ON COLUMN app.device_binding.unbound_at IS 'UTC time the binding ended; null while active.';
COMMENT ON COLUMN app.device_binding.unbound_by IS 'Id of the user who ended the binding.';

COMMENT ON TABLE app.device_directive IS 'A signed remote directive sent to a phone, with delivery and acknowledgement times.
owner: backend:config | capture: ONLINE | retention: ops | pii: none';
COMMENT ON COLUMN app.device_directive.directive_id IS 'UUID of the directive, used by the phone to acknowledge it.';
COMMENT ON COLUMN app.device_directive.device_id IS 'Phone (app.device) the row came from, taken from the token, never from the body.';
COMMENT ON COLUMN app.device_directive.type IS 'Directive type: send_status, redownload_bundle, upload_support_bundle or resend_from.';
COMMENT ON COLUMN app.device_directive.params IS 'JSON parameters of the directive.';
COMMENT ON COLUMN app.device_directive.sig IS 'ES256 signature by the device key over the record (header records only).';
COMMENT ON COLUMN app.device_directive.created_by IS 'User who created the row (null for migrations and jobs).';
COMMENT ON COLUMN app.device_directive.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.device_directive.expires_at IS 'UTC instant after which the row is no longer valid.';
COMMENT ON COLUMN app.device_directive.delivered_at IS 'UTC time the directive was delivered to the phone.';
COMMENT ON COLUMN app.device_directive.acked_at IS 'UTC time the phone acknowledged the directive.';

COMMENT ON TABLE app.device_nonce IS 'Single-use server nonce for a Play Integrity request or key attestation.
owner: backend:auth | capture: SERVER | retention: session | pii: none';
COMMENT ON COLUMN app.device_nonce.nonce_sha256 IS 'SHA-256 of the nonce issued to the device.';
COMMENT ON COLUMN app.device_nonce.device_id IS 'Phone (app.device) the row came from, taken from the token, never from the body.';
COMMENT ON COLUMN app.device_nonce.purpose IS 'Purpose of the fix or photo; allowed values are listed under constraints.';
COMMENT ON COLUMN app.device_nonce.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.device_nonce.expires_at IS 'UTC instant after which the row is no longer valid.';
COMMENT ON COLUMN app.device_nonce.used_at IS 'UTC time the nonce was consumed; null while unused.';

COMMENT ON TABLE app.device_otp IS 'One-time code a TSO issues to bind a phone to a user, stored as hash and encrypted for display.
owner: backend:auth | capture: ONLINE | retention: session | pii: secret';
COMMENT ON COLUMN app.device_otp.id IS 'Server surrogate key.';
COMMENT ON COLUMN app.device_otp.user_id IS 'User (app.app_user); for device records the capturing user from the token.';
COMMENT ON COLUMN app.device_otp.otp_cipher IS '[pii:secret] One-time code encrypted so the TSO can read it while it is unexpired.';
COMMENT ON COLUMN app.device_otp.otp_sha256 IS '[pii:secret] SHA-256 of the one-time code, used to verify the entry.';
COMMENT ON COLUMN app.device_otp.device_model IS 'Model of the phone the code was issued for, if known.';
COMMENT ON COLUMN app.device_otp.issued_by IS 'Id of the TSO or support user who issued the code.';
COMMENT ON COLUMN app.device_otp.reason IS 'Reason given for the change or action (free text).';
COMMENT ON COLUMN app.device_otp.created_at IS 'UTC instant the row was inserted on the server.';
COMMENT ON COLUMN app.device_otp.expires_at IS 'UTC instant after which the row is no longer valid.';
COMMENT ON COLUMN app.device_otp.attempts IS 'Wrong attempts made against the code.';
COMMENT ON COLUMN app.device_otp.consumed_at IS 'UTC time the code was used; null while unused.';
COMMENT ON COLUMN app.device_otp.revoked_at IS 'UTC instant the row was revoked; null while valid.';

COMMENT ON TABLE app.device_policy IS 'The device policy rendered for a phone at a given policy version, with its hash.
owner: backend:config | capture: SERVER | retention: ops | pii: none';
COMMENT ON COLUMN app.device_policy.device_id IS 'Phone (app.device) the row came from, taken from the token, never from the body.';
COMMENT ON COLUMN app.device_policy.policy_version IS 'Policy version, equal to the config version at render time.';
COMMENT ON COLUMN app.device_policy.lockdown_level IS 'Device policy lockdown level: dev or prod.';
COMMENT ON COLUMN app.device_policy.policy IS 'The rendered device policy as JSON.';
COMMENT ON COLUMN app.device_policy.policy_sha256 IS 'SHA-256 of the rendered policy.';
COMMENT ON COLUMN app.device_policy.rendered_at IS 'UTC time the policy was rendered.';
COMMENT ON COLUMN app.device_policy.fetched_at IS 'UTC time the phone first downloaded this policy.';
COMMENT ON COLUMN app.device_policy.applied_at IS 'UTC time the phone was first seen applying this version, from its next status report.';

COMMENT ON TABLE app.device_status_report IS 'One report of a phone''s lockdown, settings, pending rows and battery state.
owner: backend:auth | capture: OFFLINE | retention: telemetry | pii: none';
COMMENT ON COLUMN app.device_status_report.id IS 'Server surrogate key.';
COMMENT ON COLUMN app.device_status_report.client_uuid IS 'UUID v4 generated on the phone when the record was committed; the idempotency key of sync.';
COMMENT ON COLUMN app.device_status_report.source IS 'Where the row came from; allowed values are listed under constraints.';
COMMENT ON COLUMN app.device_status_report.device_id IS 'Phone (app.device) the row came from, taken from the token, never from the body.';
COMMENT ON COLUMN app.device_status_report.user_id IS 'User (app.app_user); for device records the capturing user from the token.';
COMMENT ON COLUMN app.device_status_report.business_date IS 'Asia/Dhaka business date of the row (cutoff 00:00 Dhaka); all day-level rollups key off it.';
COMMENT ON COLUMN app.device_status_report.reported_at IS 'UTC time the phone produced the report.';
COMMENT ON COLUMN app.device_status_report.received_at IS 'UTC instant the server received the row.';
COMMENT ON COLUMN app.device_status_report.config_version IS 'Global config version in force for the row (at capture for device records).';
COMMENT ON COLUMN app.device_status_report.trigger IS 'Event that caused the report, such as enrolment, check_in or boot.';
COMMENT ON COLUMN app.device_status_report.app_version IS 'App version as versionName+versionCode, e.g. 1.0.3+103.';
COMMENT ON COLUMN app.device_status_report.device_owner IS 'True when the Aron app was device owner of the phone at the time.';
COMMENT ON COLUMN app.device_status_report.lockdown_level_applied IS 'Lockdown level the phone enforces: dev or prod.';
COMMENT ON COLUMN app.device_status_report.policy_version_applied IS 'Policy version the phone reports applying.';
COMMENT ON COLUMN app.device_status_report.blocking_active IS 'True when app blocking is active on the phone.';
COMMENT ON COLUMN app.device_status_report.location_enabled IS 'True when device location services are on.';
COMMENT ON COLUMN app.device_status_report.dev_options_enabled IS 'True when Android developer options are on.';
COMMENT ON COLUMN app.device_status_report.adb_enabled IS 'True when USB debugging is on.';
COMMENT ON COLUMN app.device_status_report.auto_time_enabled IS 'True when automatic network time is on.';
COMMENT ON COLUMN app.device_status_report.mock_location_apps IS 'Packages on the phone that hold mock-location permission.';
COMMENT ON COLUMN app.device_status_report.pending_rows IS 'Rows waiting to upload on the phone.';
COMMENT ON COLUMN app.device_status_report.battery_pct IS 'Battery level in percent at report time.';
COMMENT ON COLUMN app.device_status_report.integrity_verdict IS 'Integrity result the phone obtained: pass, fail, unevaluated or stale.';
COMMENT ON COLUMN app.device_status_report.report IS 'JSON report as received, with the Play Integrity token removed.';
COMMENT ON COLUMN app.device_status_report.created_at IS 'UTC instant the row was inserted on the server.';

COMMENT ON TABLE app.dirty_key IS 'Work queue entry naming a bundle snapshot or aggregate row that the worker must rebuild.
owner: backend:platform | capture: SERVER | retention: ops | pii: none';
COMMENT ON COLUMN app.dirty_key.kind IS 'Kind of the row; allowed values are listed under constraints.';
COMMENT ON COLUMN app.dirty_key.subject_id IS 'Id of the subject to rebuild; its meaning depends on kind (user, route, zone, outlet or device).';
