COMMENT ON COLUMN app.dirty_key.last_dirtied_at IS 'UTC time the key was last marked dirty.';
COMMENT ON COLUMN app.dirty_key.dirty_count IS 'Number of times the key was marked dirty since it was queued.';
COMMENT ON COLUMN app.dirty_key.reason IS 'Reason given for the change or action (free text).';
COMMENT ON COLUMN app.dirty_key.claimed_at IS 'UTC time a worker claimed the key; null when unclaimed.';
