COMMENT ON COLUMN dw.v_daily_sku.free_qty_base IS 'Free quantity given, in base units.';
COMMENT ON COLUMN dw.v_daily_sku.issued_qty_base IS 'Quantity issued to the route''s stock, in base units.';
COMMENT ON COLUMN dw.v_daily_sku.returned_qty_base IS 'Quantity returned from the route''s stock, in base units.';
COMMENT ON COLUMN dw.v_daily_sku.gross_mtk IS 'Gross sales value before discounts, in milli-taka.';
COMMENT ON COLUMN dw.v_daily_sku.memo_count IS 'Active memos containing the SKU.';
COMMENT ON COLUMN dw.v_daily_sku.updated_at IS 'UTC instant of the last update.';

COMMENT ON VIEW dw.v_daily_sr IS 'Stable view: per field user and business date, SR calls, successful calls, geo validity and memo money from the dw facts.
owner: worker | capture: SERVER | retention: event_fact | pii: none';
COMMENT ON COLUMN dw.v_daily_sr.business_date IS 'Asia/Dhaka business date of the row (cutoff 00:00 Dhaka); all day-level rollups key off it.';
COMMENT ON COLUMN dw.v_daily_sr.user_id IS 'User (app.app_user); for device records the capturing user from the token.';
COMMENT ON COLUMN dw.v_daily_sr.route_ids IS 'Routes the user called on that day.';
COMMENT ON COLUMN dw.v_daily_sr.visits IS 'Number of visits.';
COMMENT ON COLUMN dw.v_daily_sr.visited_outlets IS 'Distinct outlets visited in SR calls not abandoned or declined.';
COMMENT ON COLUMN dw.v_daily_sr.successful_calls IS 'Distinct outlets with an active memo with at least one line.';
COMMENT ON COLUMN dw.v_daily_sr.geo_valid_visits IS 'SR calls in range by the server''s re-check.';
COMMENT ON COLUMN dw.v_daily_sr.geo_valid_pct IS 'geo_valid_visits / visits x 100; null when there were no visits.';
COMMENT ON COLUMN dw.v_daily_sr.force_sale_visits IS 'SR calls whose geo action was force_sale.';
COMMENT ON COLUMN dw.v_daily_sr.mock_visits IS 'SR calls with a mocked fix.';
COMMENT ON COLUMN dw.v_daily_sr.active_memo_count IS 'Number of active (not voided or superseded) memos with at least one line.';
COMMENT ON COLUMN dw.v_daily_sr.gross_mtk IS 'Gross sales value before discounts, in milli-taka.';
COMMENT ON COLUMN dw.v_daily_sr.net_mtk IS 'Net payable value in milli-taka (gross minus discounts and QC deduction, rounded to the paisa).';
COMMENT ON COLUMN dw.v_daily_sr.due_mtk IS 'Amount left on credit (due) in milli-taka.';
COMMENT ON COLUMN dw.v_daily_sr.memos_captured_offline IS 'Memos captured while the phone was offline.';
COMMENT ON COLUMN dw.v_daily_sr.first_visit_at IS 'UTC instant the first call opened.';
COMMENT ON COLUMN dw.v_daily_sr.last_visit_end_at IS 'UTC instant the last call ended.';

COMMENT ON VIEW dw.v_geo_integrity IS 'Stable view: per user and business date, geo-validation outcomes of visits and mock-location evidence of fixes.
owner: worker | capture: SERVER | retention: event_fact | pii: none';
COMMENT ON COLUMN dw.v_geo_integrity.business_date IS 'Asia/Dhaka business date of the row (cutoff 00:00 Dhaka); all day-level rollups key off it.';
COMMENT ON COLUMN dw.v_geo_integrity.user_id IS 'User (app.app_user); for device records the capturing user from the token.';
COMMENT ON COLUMN dw.v_geo_integrity.visits IS 'Number of visits.';
COMMENT ON COLUMN dw.v_geo_integrity.server_in_range IS 'Visits in range by the server''s re-check.';
COMMENT ON COLUMN dw.v_geo_integrity.geo_valid_pct IS 'server_in_range / visits x 100; null when there were no visits.';
COMMENT ON COLUMN dw.v_geo_integrity.server_out_of_range IS 'Visits out of range by the server''s re-check.';
COMMENT ON COLUMN dw.v_geo_integrity.no_fix IS 'Visits where the phone got no location fix.';
COMMENT ON COLUMN dw.v_geo_integrity.accuracy_too_low IS 'Visits whose fix was less accurate than the allowed maximum.';
COMMENT ON COLUMN dw.v_geo_integrity.mocked_visits IS 'Visits with a mocked fix.';
COMMENT ON COLUMN dw.v_geo_integrity.force_sale_visits IS 'Visits whose geo action was force_sale.';
COMMENT ON COLUMN dw.v_geo_integrity.blocked_visits IS 'Visits blocked by the mock-location policy.';
COMMENT ON COLUMN dw.v_geo_integrity.device_server_mismatch IS 'Visits where the server''s verdict differs from the phone''s.';
COMMENT ON COLUMN dw.v_geo_integrity.fixes IS 'Location fixes received for the user-day.';
COMMENT ON COLUMN dw.v_geo_integrity.mock_fixes IS 'Fixes flagged as mock locations.';
COMMENT ON COLUMN dw.v_geo_integrity.avg_accuracy_m IS 'Average fix accuracy in metres (1 decimal).';
